cy.request({
  method: "PUT",
  url: apiUrl + "/orders/add",
  headers: {
    Authorization: "Bearer " + token
  },
  body: {
    product: 9,
    quantity: 1
  }
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.have.property("orderLines").and.to.be.an("array");
  orderLineId = response.body.orderLines[0].id;
  expect(orderLineId).to.be.a("number");
});

cy.request({
  method: "PUT",
  url: `${apiUrl}/orders/${orderLineId}/change-quantity`,
  headers: {
    Authorization: "Bearer " + token
  },
  body: {
    quantity: 2
  }
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.have.property("orderLines").and.to.be.an("array");
  response.body.orderLines.forEach(line => {
    // Vérifie que chaque ligne de commande a une propriété "quantity"
    expect(line).to.have.property("quantity").and.to.be.a("number").and.to.be.greaterThan(0);
  });
});

const fakeOrderLineId = 999999;
cy.request({
  method: "PUT",
  url: `${apiUrl}/orders/${fakeOrderLineId}/change-quantity`,
  headers: {
    Authorization: "Bearer " + token,
    Accept: "application/json"
  },
  body: {
    quantity: 2
  },
  failOnStatusCode: false
}).then(response => {
  expect(response.status).to.eq(404);
  if (typeof response.body === "string") {
    expect(response.body).to.include("Produit non trouvé");
  }
});
